def summary(label: str) -> dict | None:
    h = SUMMARY_HELP.get(label)
    return {"why": h[0], "fix": h[1], "h1": "Qué significa", "h2": "Qué mirar"} if h else None


def option(key: str) -> dict | None:
    h = OPTION_HELP.get(key)
    return {"why": h[0], "fix": h[1]} if h else None


def tab(key: str) -> dict | None:
    h = TAB_HELP.get(key)
    return {"why": h[0], "fix": h[1]} if h else None


def english() -> dict[str, str]:
    """Spanish -> English pairs for the interface translator."""
    out: dict[str, str] = {}
    for h in (*OPTION_HELP.values(), *TAB_HELP.values(), *SUMMARY_HELP.values()):
        out[h[0]], out[h[1]] = h[2], h[3]
    return out
